import{_ as r,y as s,a as i,o as a,a2 as t,D as n}from"./chunks/framework.DCcmcJcL.js";const _=JSON.parse('{"title":"GDPR","description":"","frontmatter":{},"headers":[],"relativePath":"configure/gdpr.md","filePath":"configure/gdpr.md","lastUpdated":1789331284000}'),g={name:"configure/gdpr.md"};function c(l,e,h,p,d,u){const o=s("ImagePopup");return a(),i("div",null,[e[0]||(e[0]=t('<h1 id="gdpr" tabindex="-1">GDPR <a class="header-anchor" href="#gdpr" aria-label="Permalink to &quot;GDPR&quot;">​</a></h1><p>Bagisto&#39;s GDPR (General Data Protection Regulation) features let customers see and control the personal data you hold, and let you record their consent. Every setting on this page is per channel and per locale, so switch both at the top of the page to cover each store and language.</p><p>Go to <strong>Configure &gt;&gt; General &gt;&gt; GDPR</strong>.</p><h2 id="turn-gdpr-on" tabindex="-1">Turn GDPR on <a class="header-anchor" href="#turn-gdpr-on" aria-label="Permalink to &quot;Turn GDPR on&quot;">​</a></h2><ol><li>In the <strong>GDPR Compliance Settings</strong> section, switch <strong>Enable GDPR</strong> on.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',5)),n(o,{src:"/images/configure/gdpr-agreement.png",alt:"GDPR Compliance Settings"}),e[1]||(e[1]=t('<p>Once on, a <strong>GDPR Requests</strong> entry appears in the customer&#39;s account menu on the storefront with a <strong>Create Request</strong> button. Customers use it to ask for their data to be updated or deleted, and you handle those requests under <strong>Customers &gt;&gt; GDPR Data Requests</strong>.</p><h2 id="ask-for-consent-at-sign-up" tabindex="-1">Ask for consent at sign up <a class="header-anchor" href="#ask-for-consent-at-sign-up" aria-label="Permalink to &quot;Ask for consent at sign up&quot;">​</a></h2><p>The agreement adds a checkbox the customer must tick before registering.</p><ol><li>In the <strong>GDPR Agreement</strong> section, switch <strong>Enable Customer Agreement</strong> on.</li><li>Enter the <strong>Agreement Checkbox Label</strong>, the sentence shown beside the checkbox, for example <em>I agree to the terms and conditions and the privacy policy</em>.</li><li>Enter the <strong>Agreement Content</strong>, the full text shown when the shopper opens <strong>Click Here</strong> beside the checkbox.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',4)),n(o,{src:"/images/configure/gdpr-agreement2.png",alt:"GDPR Agreement settings"}),e[2]||(e[2]=t('<h2 id="show-a-cookie-notice" tabindex="-1">Show a cookie notice <a class="header-anchor" href="#show-a-cookie-notice" aria-label="Permalink to &quot;Show a cookie notice&quot;">​</a></h2><ol><li>In the <strong>Cookie Notice Settings</strong> section, switch <strong>Enable Cookie Notice</strong> on.</li><li>Choose the <strong>Cookie Block Display Position</strong>: bottom left, bottom right, top left, top right or center.</li><li>Optionally enter a <strong>Static Block Identifier</strong> to show one of your CMS blocks inside the notice.</li><li>Enter the <strong>Description</strong> shoppers read in the notice.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',2)),n(o,{src:"/images/configure/cookies-position.png",alt:"Cookie Notice Settings"}),e[3]||(e[3]=t('<h2 id="describe-the-cookie-categories" tabindex="-1">Describe the cookie categories <a class="header-anchor" href="#describe-the-cookie-categories" aria-label="Permalink to &quot;Describe the cookie categories&quot;">​</a></h2><p>The <strong>Manage Your Cookie Preferences</strong> section holds the text shown for each category a shopper can accept or refuse:</p><ul><li><strong>Strictly Necessary</strong> – cookies the site needs to work, such as the session.</li><li><strong>Basic Interactions &amp; Functionalities</strong> – cookies behind features such as chat or forms.</li><li><strong>Experience Enhancements</strong> – cookies that remember preferences such as language.</li><li><strong>Measurements</strong> – analytics cookies that measure traffic and behaviour.</li><li><strong>Targeting &amp; Advertising</strong> – cookies used for personalised marketing.</li></ul><p>Edit any of the texts and click <strong>Save Configuration</strong>.</p>',4))])}const f=r(g,[["render",c]]);export{_ as __pageData,f as default};
